package net.civeira.phylax.feature.access.resourceserver.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.resourceserver.domain.ResourceServer;
import net.civeira.phylax.feature.access.resourceserver.domain.valueobject.ApiKeyVO;

class ApiKeyValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of api key of resource server")
  void test_api_key_value_holder_assign_plain_value() {
    Object holder = new Object();
    ApiKeyValueHolder<Object> value = new ApiKeyValueHolder<>(holder);
    Assertions.assertSame(holder, value.apiKey("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getApiKeyValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getApiKey().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of api key of resource server")
  void test_api_key_value_holder_assign_value_object() {
    Object holder = new Object();
    ApiKeyValueHolder<Object> value = new ApiKeyValueHolder<>(holder);
    ApiKeyVO vo = ApiKeyVO.from("one");
    Assertions.assertFalse(value.getApiKeyValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.apiKey(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getApiKeyValue().orElseThrow());
    Assertions.assertSame(holder, value.apiKey(Optional.empty()));
    Assertions.assertFalse(value.getApiKeyValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.apiKey(Optional.of(vo)));
    Assertions.assertSame(vo, value.getApiKeyValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of api key of resource server against the original")
  void test_api_key_value_holder_read() {
    Object holder = new Object();
    ApiKeyValueHolder<Object> value = new ApiKeyValueHolder<>(holder);
    ApiKeyVO vo = ApiKeyVO.from("one");
    ApiKeyVO other = ApiKeyVO.from("one");
    ResourceServer original = Mockito.mock(ResourceServer.class);
    Mockito.when(original.getApiKeyValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readApiKey(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readApiKey(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.apiKey(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readApiKey(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readApiKey(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of api key of resource server")
  void test_api_key_value_holder_unset() {
    Object holder = new Object();
    ApiKeyValueHolder<Object> value = new ApiKeyValueHolder<>(holder);
    ApiKeyVO vo = ApiKeyVO.from("one");
    value.apiKey(vo);
    Assertions.assertSame(holder, value.unsetApiKeyIfMatches("apiKey_other"));
    Assertions.assertTrue(value.getApiKeyValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetApiKeyIfMatches("apiKey"));
    Assertions.assertFalse(value.getApiKeyValue().isPresent(),
        "The field name must clear the value");
    value.apiKey(vo);
    Assertions.assertSame(holder, value.unsetApiKey());
    Assertions.assertFalse(value.getApiKeyValue().isPresent(), "Unset must clear the value");
  }
}
